<?php
declare(strict_types=1);

/*
 * Migração 356 — textos da "Ajuda da transação" (ajuda_transacoes, guniversal_dbp) das telas de Não Conformidades.
 * Aparecem no botão ? dos grids e no painel de ajuda (F1). Chave = transação da tela (data-help-transaction) ou, nas
 * telas sem transação própria (Correção, Configuração), o código do menu. Os códigos de menu "Nova ocorrência" ficam
 * sem texto de propósito: são a primeira chave da tela da ocorrência e esconderiam o texto da aba aberta.
 * Formato: transacao => ['titulo' => [pt,en,es], 'texto' => [pt,en,es] (HTML simples: p, ul, li, b)].
 */

$L = static fn(string $pt, string $en, string $es): array => ['pt' => $pt, 'en' => $en, 'es' => $es];
$T = static fn(array $titulo, array $texto): array => ['titulo' => $titulo, 'texto' => $texto];

$textos = [
    // ------------------------------------------------------------ abas da ocorrência
    'nc_ocorrencia_ocorrencia' => $T($L('Ocorrência', 'Occurrence', 'Ocurrencia'), $L(
        '<p>Registre o problema: <b>Unidade</b>, <b>Gestor</b> (quem vai avaliar), <b>Lista de distribuição</b> (quem toma conhecimento), data, classificação, <b>Sumário</b> e <b>Descrição</b>. Os campos mudam conforme o tipo; * indica obrigatório no envio.</p><ul><li><b>Salvar</b>: grava e a NC continua Em criação.</li><li><b>Salvar e enviar ao gestor</b>: a NC vai para "Com o Gestor".</li><li>Anexos (clipe, no topo) e PDF aparecem depois da primeira gravação.</li></ul><p>Só o emitente altera esta aba, em "Em criação" ou "Recusado pelo Gestor".</p>',
        '<p>Record the problem: <b>Unit</b>, <b>Manager</b> (who will assess it), <b>Distribution list</b> (who is informed), date, classification, <b>Summary</b> and <b>Description</b>. Fields change with the type; * means required to send.</p><ul><li><b>Save</b>: stores it and the NC stays In creation.</li><li><b>Save and send to the manager</b>: the NC goes to "With the Manager".</li><li>Attachments (paperclip, at the top) and PDF show after the first save.</li></ul><p>Only the issuer changes this tab, in "In creation" or "Refused by the Manager".</p>',
        '<p>Registre el problema: <b>Unidad</b>, <b>Gestor</b> (quien la evaluará), <b>Lista de distribución</b> (quién toma conocimiento), fecha, clasificación, <b>Resumen</b> y <b>Descripción</b>. Los campos cambian según el tipo; * indica obligatorio para enviar.</p><ul><li><b>Guardar</b>: graba y la NC sigue En creación.</li><li><b>Guardar y enviar al gestor</b>: la NC pasa a "Con el Gestor".</li><li>Adjuntos (clip, arriba) y PDF aparecen después de la primera grabación.</li></ul><p>Solo el emisor cambia esta pestaña, en "En creación" o "Rechazado por el Gestor".</p>')),
    'nc_ocorrencia_gestor' => $T($L('Avaliação do gestor', 'Manager assessment', 'Evaluación del gestor'), $L(
        '<p>O gestor registra a <b>Ação imediata</b>, a <b>Análise da abrangência</b>, responde sobre riscos e mudança e escolhe o <b>Responsável</b> pela análise da causa.</p><ul><li><b>Enviar ao responsável</b>: exige ação imediata, abrangência e responsável.</li><li><b>Recusar e devolver ao emitente</b>: exige o motivo da recusa.</li><li><b>Finalizar como improcedente</b>: quando não é uma não conformidade; a NC termina.</li></ul>',
        '<p>The manager records the <b>Immediate action</b> and the <b>Scope analysis</b>, answers about risks and change and chooses the <b>Responsible</b> for the cause analysis.</p><ul><li><b>Send to the responsible</b>: requires immediate action, scope and responsible.</li><li><b>Refuse and return to the issuer</b>: requires the refusal reason.</li><li><b>Close as unfounded</b>: when it is not a non-conformity; the NC ends.</li></ul>',
        '<p>El gestor registra la <b>Acción inmediata</b> y el <b>Análisis del alcance</b>, responde sobre riesgos y cambio y elige el <b>Responsable</b> del análisis de la causa.</p><ul><li><b>Enviar al responsable</b>: exige acción inmediata, alcance y responsable.</li><li><b>Rechazar y devolver al emisor</b>: exige el motivo del rechazo.</li><li><b>Finalizar como improcedente</b>: cuando no es una no conformidad; la NC termina.</li></ul>')),
    'nc_ocorrencia_analise' => $T($L('Análise da causa e plano de ação', 'Cause analysis and action plan', 'Análisis de la causa y plan de acción'), $L(
        '<p>Três sub-abas: <b>Análise</b> (data prevista e texto da análise, evidências, Sugerir com IA), <b>Causas</b> (tipo e descrição) e <b>Plano de ação</b> (ação, responsável, início, fim, status 0–100% e arquivos).</p><p>Para <b>Enviar para a avaliação da eficácia</b>: análise, data prevista, pelo menos 1 causa, 1 ação por causa e o plano realizado. Excluir uma causa exclui as ações dela.</p><p>No Planejamento e na Assistência Técnica esta aba é só o Plano de ação, e a NC avança sozinha quando todas as ações chegam a 100%.</p>',
        '<p>Three sub-tabs: <b>Analysis</b> (expected date and analysis text, evidence, Suggest with AI), <b>Causes</b> (type and description) and <b>Action plan</b> (action, owner, start, end, status 0–100% and files).</p><p>To <b>Send to the effectiveness check</b>: analysis, expected date, at least 1 cause, 1 action per cause and the plan done. Deleting a cause deletes its actions.</p><p>In Planning and Technical Assistance this tab is just the Action plan, and the NC moves on by itself when all actions reach 100%.</p>',
        '<p>Tres sub-pestañas: <b>Análisis</b> (fecha prevista y texto del análisis, evidencias, Sugerir con IA), <b>Causas</b> (tipo y descripción) y <b>Plan de acción</b> (acción, responsable, inicio, fin, estado 0–100% y archivos).</p><p>Para <b>Enviar a la evaluación de la eficacia</b>: análisis, fecha prevista, al menos 1 causa, 1 acción por causa y el plan realizado. Eliminar una causa elimina sus acciones.</p><p>En Planificación y Asistencia Técnica esta pestaña es solo el Plan de acción, y la NC avanza sola cuando todas las acciones llegan a 100%.</p>')),
    'nc_ocorrencia_eficacia' => $T($L('Verificação da eficácia', 'Effectiveness check', 'Verificación de la eficacia'), $L(
        '<p>O gestor descreve a <b>Verificação da eficácia</b> e escolhe o <b>Resultado</b>:</p><ul><li><b>Eficaz</b> ou <b>Encerrada sem a verificação</b>: a NC é finalizada.</li><li><b>Não eficaz</b>: volta ao responsável.</li></ul><p><b>Recusar e devolver ao responsável</b> exige motivo. <b>Avaliar com IA</b> lê as evidências e dá um parecer; quem aplica o resultado é o gestor. Se a empresa exige prazo, informe a data da análise e o responsável pela pendência.</p>',
        '<p>The manager describes the <b>Effectiveness check</b> and picks the <b>Result</b>:</p><ul><li><b>Effective</b> or <b>Closed without check</b>: the NC is closed.</li><li><b>Not effective</b>: it goes back to the responsible.</li></ul><p><b>Refuse and return to the responsible</b> requires a reason. <b>Evaluate with AI</b> reads the evidence and gives an opinion; the manager applies the result. If the company requires a deadline, enter the analysis date and the owner of the pending item.</p>',
        '<p>El gestor describe la <b>Verificación de la eficacia</b> y elige el <b>Resultado</b>:</p><ul><li><b>Eficaz</b> o <b>Cerrada sin verificación</b>: la NC se finaliza.</li><li><b>No eficaz</b>: vuelve al responsable.</li></ul><p><b>Rechazar y devolver al responsable</b> exige motivo. <b>Evaluar con IA</b> lee las evidencias y da un parecer; quien aplica el resultado es el gestor. Si la empresa exige plazo, indique la fecha del análisis y el responsable de la pendiente.</p>')),
    'nc_ocorrencia_historico' => $T($L('Histórico da NC', 'NC history', 'Historial de la NC'), $L(
        '<p>Cada passagem de etapa e cada alteração da NC: data, usuário, de qual etapa para qual e o detalhe (motivos, correções da administração, uso da IA). Gravado pelo sistema; não pode ser editado.</p>',
        '<p>Every stage change and every NC change: date, user, from which stage to which and the detail (reasons, administration corrections, AI use). Written by the system; it cannot be edited.</p>',
        '<p>Cada cambio de etapa y cada alteración de la NC: fecha, usuario, de qué etapa a cuál y el detalle (motivos, correcciones de la administración, uso de la IA). Lo graba el sistema; no se puede editar.</p>')),
    // ------------------------------------------------------------ grids dentro da ocorrência
    'naoconformidades_ocorrencia_causas' => $T($L('Causas da NC', 'NC causes', 'Causas de la NC'), $L(
        '<p>As causas encontradas na análise. <b>Nova</b> cadastra (tipo de causa e descrição); selecione a linha para editar ou excluir. A coluna <b>Ações</b> mostra quantas ações a causa tem: toda causa precisa de pelo menos 1 ação para enviar à eficácia. Excluir a causa exclui as ações dela.</p>',
        '<p>The causes found in the analysis. <b>New</b> registers one (cause type and description); select the row to edit or delete. The <b>Actions</b> column shows how many actions the cause has: every cause needs at least 1 action to send to the effectiveness check. Deleting the cause deletes its actions.</p>',
        '<p>Las causas encontradas en el análisis. <b>Nueva</b> registra (tipo de causa y descripción); seleccione la fila para editar o eliminar. La columna <b>Acciones</b> muestra cuántas acciones tiene la causa: toda causa necesita al menos 1 acción para enviar a la eficacia. Eliminar la causa elimina sus acciones.</p>')),
    'naoconformidades_ocorrencia_plano' => $T($L('Plano de ação da NC', 'NC action plan', 'Plan de acción de la NC'), $L(
        '<p>As ações para eliminar as causas, cada uma com responsável, início, fim, prioridade e <b>Status</b> (0, 25, 50, 75 ou 100%). O responsável da NC cria e edita; o responsável de cada ação atualiza o status e a observação da sua. O clipe da coluna <b>Arquivos</b> guarda a evidência da ação.</p>',
        '<p>The actions to remove the causes, each with owner, start, end, priority and <b>Status</b> (0, 25, 50, 75 or 100%). The NC responsible creates and edits them; each action owner updates the status and note of their own. The paperclip in the <b>Files</b> column keeps the action evidence.</p>',
        '<p>Las acciones para eliminar las causas, cada una con responsable, inicio, fin, prioridad y <b>Estado</b> (0, 25, 50, 75 o 100%). El responsable de la NC las crea y edita; el responsable de cada acción actualiza el estado y la observación de la suya. El clip de la columna <b>Archivos</b> guarda la evidencia de la acción.</p>')),
    'naoconformidades_ocorrencia_historico' => $T($L('Histórico da NC', 'NC history', 'Historial de la NC'), $L(
        '<p>Passagens de etapa e alterações da NC, da mais recente para a mais antiga, com o usuário e o detalhe. Use o filtro das colunas para achar um evento.</p>',
        '<p>Stage changes and NC changes, newest first, with the user and the detail. Use the column filters to find an event.</p>',
        '<p>Cambios de etapa y alteraciones de la NC, del más reciente al más antiguo, con el usuario y el detalle. Use los filtros de las columnas para encontrar un evento.</p>')),
    // ------------------------------------------------------------ listas
    'naoconformidades_minhasocorrencias' => $T($L('Minhas ocorrências', 'My occurrences', 'Mis ocurrencias'), $L(
        '<p>As NCs em que você é emitente, gestor, responsável ou responsável de uma ação, inclusive as finalizadas. <b>Duplo clique</b> na linha abre a NC na aba em que você age.</p><ul><li>Coluna <b>Etapa</b>: onde a NC está.</li><li>Busca e filtros esperam 3 segundos após a digitação (Enter pesquisa na hora).</li><li>Selecione a linha e use o botão de PDF para gerar a ocorrência completa.</li></ul>',
        '<p>The NCs where you are issuer, manager, responsible or action owner, finalized ones included. <b>Double-click</b> the row to open the NC on the tab where you act.</p><ul><li><b>Stage</b> column: where the NC is.</li><li>Search and filters wait 3 seconds after typing (Enter searches at once).</li><li>Select the row and use the PDF button to create the full occurrence.</li></ul>',
        '<p>Las NC en las que usted es emisor, gestor, responsable o responsable de una acción, incluidas las finalizadas. <b>Doble clic</b> en la fila abre la NC en la pestaña en la que usted actúa.</p><ul><li>Columna <b>Etapa</b>: dónde está la NC.</li><li>La búsqueda y los filtros esperan 3 segundos después de escribir (Enter busca en el momento).</li><li>Seleccione la fila y use el botón de PDF para generar la ocurrencia completa.</li></ul>')),
    'naoconformidades_listageralocorrencias' => $T($L('Lista geral de ocorrências', 'General occurrence list', 'Lista general de ocurrencias'), $L(
        '<p>Todas as NCs que você pode ver, da mais nova para a mais antiga. Abre <b>sem as finalizadas</b>: escolha "Finalizado" no filtro <b>Etapa</b> para vê-las. Sem a permissão de visualizar o total, mostra só as NCs em que você está envolvido. <b>Duplo clique</b> abre a NC; o botão de PDF gera a ocorrência selecionada; exportar leva o que está filtrado para o Excel.</p>',
        '<p>Every NC you can see, newest first. It opens <b>without the finalized ones</b>: choose "Finalized" in the <b>Stage</b> filter to see them. Without the view-all permission, it shows only the NCs you are involved in. <b>Double-click</b> opens the NC; the PDF button creates the selected occurrence; export takes what is filtered to Excel.</p>',
        '<p>Todas las NC que usted puede ver, de la más nueva a la más antigua. Abre <b>sin las finalizadas</b>: elija "Finalizado" en el filtro <b>Etapa</b> para verlas. Sin el permiso de ver el total, muestra solo las NC en las que usted participa. <b>Doble clic</b> abre la NC; el botón de PDF genera la ocurrencia seleccionada; exportar lleva lo filtrado a Excel.</p>')),
    // ------------------------------------------------------------ administração
    'NAO_CONFORMIDADES_CORRECAO' => $T($L('Correção de ocorrência', 'Occurrence correction', 'Corrección de ocurrencia'), $L(
        '<p>Busque a NC pelo número e corrija emitente, gestor, responsável, responsáveis das ações, data (não futura), unidade, lista, sumário, descrição, ação imediata, abrangência e, conforme o tipo, fornecedor, quantidades e cliente. O <b>Motivo</b> (mínimo 5 caracteres) é obrigatório.</p><p>A etapa só muda por <b>Reabrir</b> (NC finalizada volta à etapa anterior), <b>Devolver uma etapa</b> ou <b>Encerrar administrativamente</b>; o botão mostra o destino. Tudo vai para o histórico da NC e os novos gestor/responsável são avisados. Até a virada, só NCs a partir de 50001.</p>',
        '<p>Find the NC by number and fix issuer, manager, responsible, action owners, date (not in the future), unit, list, summary, description, immediate action, scope and, depending on the type, supplier, quantities and customer. The <b>Reason</b> (at least 5 characters) is required.</p><p>The stage only changes through <b>Reopen</b> (a finalized NC goes back to the previous stage), <b>Return one stage</b> or <b>Close administratively</b>; the button shows the target. Everything goes to the NC history and the new manager/responsible are notified. Until the cut-over, only NCs from 50001.</p>',
        '<p>Busque la NC por número y corrija emisor, gestor, responsable, responsables de las acciones, fecha (no futura), unidad, lista, resumen, descripción, acción inmediata, alcance y, según el tipo, proveedor, cantidades y cliente. El <b>Motivo</b> (mínimo 5 caracteres) es obligatorio.</p><p>La etapa solo cambia con <b>Reabrir</b> (la NC finalizada vuelve a la etapa anterior), <b>Devolver una etapa</b> o <b>Cerrar administrativamente</b>; el botón muestra el destino. Todo va al historial de la NC y los nuevos gestor/responsable reciben el aviso. Hasta el cambio, solo NC desde 50001.</p>')),
    'naoconformidades_correcao_busca' => $T($L('NCs encontradas', 'NCs found', 'NC encontradas'), $L(
