    'naoconformidades_correcao_historico' => $T($L('Histórico da NC', 'NC history', 'Historial de la NC'), $L(
        '<p>Tudo o que aconteceu com a NC, inclusive as correções da administração com "antes → depois" e o motivo.</p>',
